        self.values["id"] = ","
        self.values["od"] = ","
        self.values["oq"] = "\""
        self.values["ir"] = 1
        self.values["is"] = 0
        self.values["ilr"] = 0
        self.values["driver"] = ""
        self.values["dsn"] = ""
        self.values["db"] = ""
        self.values["config"] = ""
        self.values["q"] = ""
        self.values["t"] = ""
        self.values["a"] = ""
        self.values["A"] = ""
        self.values["ijq"] = ""
        self.values["inull"] = ""
        self.values["onull"] = ""
        self.values["out"] = ""
        self.values["oz"] = ""
        for b in self.BOOL_FLAGS:
            self.values[b] = False
        # Explicitly flagged (i.e. user passed the option).
        self.set = set()

    def get(self, name):
        return self.values.get(name)

    def parse(self, argv):
        i = 0
        rest = []
        while i < len(argv):
            arg = argv[i]
            if not arg.startswith("-") or arg == "-":
                rest = argv[i:]
                break
            if arg == "--":
                rest = argv[i + 1:]
                break
            name = arg.lstrip("-")
            value = None
            if "=" in name:
                name, value = name.split("=", 1)
            if name in self.BOOL_FLAGS:
                if value is None:
                    self.values[name] = True
                else:
                    lv = value.lower()
                    if lv in ("true", "1", "t"):
                        self.values[name] = True
                    elif lv in ("false", "0", "f"):
                        self.values[name] = False
                    else:
                        raise FlagError(f'invalid boolean value "{value}" for -{name}: parse error')
                self.set.add(name)
            elif name in self.STRING_FLAGS:
                if value is None:
                    i += 1
                    if i >= len(argv):
                        raise FlagError(f"flag needs an argument: -{name}")
                    value = argv[i]
                self.values[name] = value
                self.set.add(name)
            elif name in self.INT_FLAGS:
                if value is None:
                    i += 1
                    if i >= len(argv):
                        raise FlagError(f"flag needs an argument: -{name}")
                    value = argv[i]
