    # Prepare SQLite.
    conn = sqlite3.connect(":memory:")
    try:
        cur = conn.cursor()
        for raw, file_path, tbl in loaded:
            cols_sql = ", ".join(f"`{c}` text" for c in tbl.columns)
            cur.execute(f"CREATE TEMPORARY TABLE `{file_path}` ( {cols_sql} );")
