    Whitespace runs become single " " tokens, punctuation is separated, and
    quoted strings (single/double/back-tick) come out intact including quotes.
    """
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c == "\n":
            tokens.append("\n")
            i += 1
        elif c.isspace():
            tokens.append(" ")
            i += 1
        elif c in ("'", '"', "`"):
            quote = c
            j = i + 1
            while j < n:
                if sql[j] == quote:
                    if j + 1 < n and sql[j + 1] == quote:
                        j += 2
                        continue
                    j += 1
                    break
                j += 1
            tokens.append(sql[i:j])
            i = j
        elif _IDENT_RE.match(c):
            j = i
            while j < n and _IDENT_RE.match(sql[j]):
                j += 1
            tokens.append(sql[i:j])
            i = j
        else:
            tokens.append(c)
            i += 1
    return tokens


