        stripped = ln[i:]
        if stripped.startswith("- "):
            items = []
            while True:
                ln = cur_line()
                if ln is None:
                    break
                ci = indent_of(ln)
                if ci != i:
                    break
                s = ln[ci:]
                if not s.startswith("-"):
                    break
                rest = s[1:].lstrip(" ")
                if not rest:
                    pos[0] += 1
                    item = parse_block(i + 1)
                    items.append(item)
                elif ":" in rest and not rest.startswith(("'", '"')):
                    # inline "- key: value" with possible continuation.
                    # treat same line as first key of a map.
                    key, _, val = rest.partition(":")
                    val = val.strip()
                    obj = {}
                    obj[key.strip()] = parse_value(val) if val else None
                    pos[0] += 1
                    # continuation at indent i + 2
                    while True:
                        ln2 = cur_line()
                        if ln2 is None:
                            break
                        ci2 = indent_of(ln2)
                        if ci2 <= i:
                            break
                        s2 = ln2[ci2:]
                        if ":" in s2:
                            k, _, v = s2.partition(":")
                            obj[k.strip()] = parse_value(v.strip())
                            pos[0] += 1
                        else:
                            break
                    items.append(obj)
                else:
                    items.append(parse_value(rest))
                    pos[0] += 1
            return items
        # mapping
        obj = {}
        while True:
            ln = cur_line()
            if ln is None:
                break
            ci = indent_of(ln)
            if ci != i:
                break
            s = ln[ci:]
            if s.startswith("-"):
                break
            if ":" not in s:
                break
            k, _, v = s.partition(":")
            v = v.strip()
            pos[0] += 1
            if v == "":
                sub = parse_block(i + 1)
                obj[k.strip()] = sub
            else:
                obj[k.strip()] = parse_value(v)
        return obj

    return parse_block(0)


def read_tbln(fh):
    header = []
    types = []
    rows = []
    for line in fh:
        line = line.rstrip("\r\n")
        if not line:
            continue
        if line.startswith(";"):
            body = line[1:].strip()
            if body.startswith("name:"):
                header = _split_tbln(body[len("name:"):].strip())
            elif body.startswith("type:"):
                types = _split_tbln(body[len("type:"):].strip())
        elif line.startswith("|"):
            row = _split_tbln(line)
            rows.append(row)
    return header, types, rows


def _split_tbln(line: str):
    s = line.strip()
    if s.startswith("|"):
        s = s[1:]
    if s.endswith("|"):
        s = s[:-1]
    return [x.strip() for x in s.split("|")]


def read_text(fh):
    rows = []
    for line in fh:
        rows.append([line.rstrip("\n")])
    return rows


def read_width(fh):
    lines = [line.rstrip("\n") for line in fh]
    while lines and not lines[-1].strip():
        lines.pop()
    rows = []
    for line in lines:
        # Split on runs of 2+ spaces to keep column alignment intact.
        parts = re.split(r" {2,}", line.strip())
        rows.append([p.strip() for p in parts])
    # Normalise to widest row
    maxc = max((len(r) for r in rows), default=0)
    for r in rows:
        while len(r) < maxc:
            r.append("")
    return rows


# ---------------------------------------------------------------------------
# Table loading
# ---------------------------------------------------------------------------

class Table:
    def __init__(self, name: str, columns, rows):
        self.name = name
        self.columns = columns
        self.rows = rows  # list of lists


def load_table(path: str, flags: Flags, forced_format: str = ""):
    fmt = forced_format
    if not fmt:
        fmt = guess_format_by_ext(path) or "CSV"
    if path == "-":
        fh = open_input("-")
    else:
        if not os.path.exists(path):
            raise ImportError_(f"open {path}: no such file or directory")
        fh = open_input(path)
    try:
        data = fh.read()
    finally:
        fh.close()

    inull = flags.get("inull") if "inull" in flags.set else None
    skip = flags.get("is") or 0
    if skip:
        lines = data.splitlines(keepends=True)
        data = "".join(lines[skip:])
    preread = flags.get("ir") or 1
    limit = flags.get("ilr") or 0

    if fmt in ("JSON", "JSONL"):
        obj_rows = read_json(data, flags.get("ijq") or "")
        if not obj_rows:
            raise ImportError_("no rows")
        columns = []
        for i, r in enumerate(obj_rows):
            if i >= preread and preread > 0:
                break
            for k in r.keys():
                if k not in columns:
                    columns.append(k)
        if not columns and obj_rows:
            for k in obj_rows[0].keys():
                if k not in columns:
                    columns.append(k)
        rows = [[r.get(c, "") for c in columns] for r in obj_rows]
    elif fmt == "LTSV":
        header, obj_rows = read_ltsv(io.StringIO(data))
        if not obj_rows:
            raise ImportError_("no rows")
        columns = []
        for i, r in enumerate(obj_rows):
            if i >= preread and preread > 0:
                break
            for k in r.keys():
                if k not in columns:
                    columns.append(k)
        rows = [[r.get(c, "") for c in columns] for r in obj_rows]
    elif fmt == "YAML":
        obj_rows = read_yaml(data)
        if not obj_rows:
            raise ImportError_("no rows")
        columns = []
        for i, r in enumerate(obj_rows):
            if i >= preread and preread > 0:
                break
            for k in r.keys():
                if k not in columns:
                    columns.append(k)
        rows = [[r.get(c, "") for c in columns] for r in obj_rows]
    elif fmt == "TBLN":
        header, types, rows = read_tbln(io.StringIO(data))
        if not rows:
            raise ImportError_("no rows")
        columns = header if header else [f"c{i+1}" for i in range(len(rows[0]))]
    elif fmt == "TEXT":
        rows = read_text(io.StringIO(data))
        columns = ["text"]
    elif fmt == "WIDTH":
        rows = read_width(io.StringIO(data))
        if not rows:
            raise ImportError_("no rows")
        columns = [f"c{i+1}" for i in range(len(rows[0]))]
    else:  # CSV / TSV / default
        delim = flags.get("id") or ","
        if fmt == "TSV":
            delim = "\t"
        rows = read_csv_rows(io.StringIO(data), delimiter=delim)
        if not rows:
            raise ImportError_("no rows")
        if flags.get("ih"):
            columns = rows[0]
            rows = rows[1:]
        else:
            maxc = max(len(r) for r in rows)
            columns = [f"c{i+1}" for i in range(maxc)]
        # Pad
        maxc = max(len(r) for r in rows) if rows else len(columns)
        for r in rows:
            while len(r) < len(columns):
                r.append("")
        if not rows:
            raise ImportError_("no rows")

    if limit > 0:
        rows = rows[:limit]

    # Apply input NULL replacement.
    if inull is not None:
        for r in rows:
            for i, v in enumerate(r):
                if v == inull:
                    r[i] = None

    # Pad rows to column count, fill missing with "".
    for r in rows:
        while len(r) < len(columns):
            r.append("")

    if flags.get("inum"):
        columns = ["num"] + list(columns)
        rows = [[str(i + 1)] + list(r) for i, r in enumerate(rows)]

    return Table(path, columns, rows), fmt


# ---------------------------------------------------------------------------
# Output writers
# ---------------------------------------------------------------------------


class Writer:
    def __init__(self, flags: Flags, out_fh):
        self.flags = flags
        self.out = out_fh
        self.newline = "\r\n" if flags.get("ocrlf") else "\n"
        self.null = flags.get("onull") if "onull" in flags.set else ""

    def write(self, columns, rows):
        raise NotImplementedError

    def _nullify(self, v):
        if v is None:
            return self.null
        return v


def _stringify_row(row, null_str):
    out = []
    for v in row:
        if v is None:
            out.append(null_str)
        elif isinstance(v, bool):
            out.append("true" if v else "false")
        elif isinstance(v, float):
            if v.is_integer():
                out.append(str(int(v)))
            else:
                out.append(repr(v))
        else:
            out.append(str(v))
    return out


class CSVWriter(Writer):
    def __init__(self, flags, out_fh, delim=None, quote=None):
        super().__init__(flags, out_fh)
        self.delim = delim if delim is not None else flags.get("od")
        self.quote = quote if quote is not None else flags.get("oq")
        self.all_quote = flags.get("oaq")

    def _encode(self, v):
        s = v
        need = self.all_quote or any(c in s for c in (self.delim, self.quote, "\n", "\r"))
        if self.quote and need:
            return self.quote + s.replace(self.quote, self.quote * 2) + self.quote
        return s

    def write(self, columns, rows):
        out_rows = []
        if self.flags.get("oh"):
            out_rows.append(columns)
        for r in rows:
            out_rows.append(_stringify_row(r, self.null))
        for r in out_rows:
            line = self.delim.join(self._encode(v) for v in r)
            self.out.write(line + self.newline)


class RawWriter(Writer):
    def __init__(self, flags, out_fh):
        super().__init__(flags, out_fh)
        self.delim = flags.get("od")

    def write(self, columns, rows):
        out_rows = []
        if self.flags.get("oh"):
            out_rows.append(columns)
        for r in rows:
            out_rows.append(_stringify_row(r, self.null))
        for r in out_rows:
            self.out.write(self.delim.join(r) + self.newline)


class LTSVWriter(Writer):
    def write(self, columns, rows):
        for r in rows:
            vals = _stringify_row(r, self.null)
            parts = [f"{c}:{v}" for c, v in zip(columns, vals)]
            self.out.write("\t".join(parts) + self.newline)


class JSONWriter(Writer):
    def write(self, columns, rows):
        objs = []
        for r in rows:
            o = {}
            for c, v in zip(columns, r):
                o[c] = _json_value(v, self.null)
            objs.append(o)
        text = json.dumps(objs, ensure_ascii=False, indent=2)
        # Ensure CRLF if needed.
        if self.newline != "\n":
            text = text.replace("\n", self.newline)
        self.out.write(text + self.newline)


class JSONLWriter(Writer):
    def write(self, columns, rows):
        for r in rows:
            o = {}
            for c, v in zip(columns, r):
                o[c] = _json_value(v, self.null)
            self.out.write(json.dumps(o, ensure_ascii=False, separators=(",", ":")) + self.newline)


def _json_value(v, null_str):
    if v is None:
        return null_str if null_str != "" else None
    if isinstance(v, (int, float, bool)):
        return v
    return str(v)


class YAMLWriter(Writer):
    def write(self, columns, rows):
        lines = []
        for r in rows:
            first = True
            for c, v in zip(columns, r):
                prefix = "- " if first else "  "
                first = False
                lines.append(f"{prefix}{c}: {_yaml_scalar(v, self.null)}")
        self.out.write("\n".join(lines) + self.newline)


def _yaml_scalar(v, null_str):
    if v is None:
        return null_str
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, (int, float)):
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        return str(v)
    s = str(v)
    return s


class MDWriter(Writer):
    def write(self, columns, rows):
        str_rows = [[_md_escape(v) for v in _stringify_row(r, self.null)] for r in rows]
        widths = [_display_width(c) for c in columns]
        for r in str_rows:
            for i, v in enumerate(r):
                if i < len(widths):
                    widths[i] = max(widths[i], _display_width(v))
                else:
                    widths.append(_display_width(v))
        header = "| " + " | ".join(_pad_centre(c, widths[i]) for i, c in enumerate(columns)) + " |"
        sep = "|" + "|".join("-" * (widths[i] + 2) for i in range(len(columns))) + "|"
        out = [header, sep]
        for r in str_rows:
            out.append("| " + " | ".join(_pad_cell(r[i], widths[i], _is_numeric(r[i])) for i in range(len(columns))) + " |")
        self.out.write(self.newline.join(out) + self.newline)


def _md_escape(v):
    return v.replace("|", "\\|")


class ATWriter(Writer):
    def write(self, columns, rows):
        str_rows = [_stringify_row(r, self.null) for r in rows]
        widths = [_display_width(c) for c in columns]
        for r in str_rows:
            for i, v in enumerate(r):
                if i < len(widths):
                    widths[i] = max(widths[i], _display_width(v))
        border = "+" + "+".join("-" * (widths[i] + 2) for i in range(len(columns))) + "+"
        header = "| " + " | ".join(_pad_centre(c, widths[i]) for i, c in enumerate(columns)) + " |"
        lines = [border, header, border]
        for r in str_rows:
            lines.append("| " + " | ".join(_pad_cell(r[i], widths[i], _is_numeric(r[i])) for i in range(len(columns))) + " |")
        lines.append(border)
        self.out.write(self.newline.join(lines) + self.newline)


class VFWriter(Writer):
    def write(self, columns, rows):
        str_rows = [_stringify_row(r, self.null) for r in rows]
        key_w = max((len(c) for c in columns), default=0)
        lines = []
        total = len(rows)
        num_w = len(str(total))
        for idx, r in enumerate(str_rows, 1):
            header = f"---[{idx:>{num_w + 1}}]------------------------"
            lines.append(header)
            for c, v in zip(columns, r):
                lines.append(f"  {c.rjust(key_w)} | {v}")
        self.out.write(self.newline.join(lines) + self.newline)


class TBLNWriter(Writer):
    def write(self, columns, rows):
        lines = []
        lines.append("; name: | " + " | ".join(columns) + " |")
        types = ["text"] * len(columns)
        lines.append("; type: | " + " | ".join(types) + " |")
        for r in rows:
            vals = _stringify_row(r, self.null)
            lines.append("| " + " | ".join(vals) + " |")
        self.out.write(self.newline.join(lines) + self.newline)


def _display_width(s):
    w = 0
    for ch in s:
        o = ord(ch)
        if o == 0:
            continue
        # East-Asian wide approximation.
        if (
            0x1100 <= o <= 0x115F or
            0x2E80 <= o <= 0xA4CF and ch not in "\u303F" or
            0xAC00 <= o <= 0xD7A3 or
            0xF900 <= o <= 0xFAFF or
            0xFE30 <= o <= 0xFE4F or
            0xFF00 <= o <= 0xFF60 or
            0xFFE0 <= o <= 0xFFE6 or
            0x20000 <= o <= 0x2FFFD or
            0x30000 <= o <= 0x3FFFD
        ):
            w += 2
        else:
            w += 1
    return w


def _pad_centre(s, width):
    cur = _display_width(s)
    if cur >= width:
        return s
    left = (width - cur) // 2
    right = width - cur - left
    return " " * left + s + " " * right


def _pad_cell(s, width, numeric):
    cur = _display_width(s)
    if cur >= width:
        return s
    pad = " " * (width - cur)
    if numeric:
        return pad + s
    return s + pad


_NUMERIC_RE = re.compile(r"^-?\d+(\.\d+)?$")


def _is_numeric(s):
    return bool(_NUMERIC_RE.match(s))


# ---------------------------------------------------------------------------
# Output
# ---------------------------------------------------------------------------


def choose_writer(fmt: str, flags: Flags, out_fh):
    fmt = fmt.upper()
    if fmt == "CSV":
        return CSVWriter(flags, out_fh)
    if fmt == "LTSV":
        return LTSVWriter(flags, out_fh)
    if fmt == "JSON":
        return JSONWriter(flags, out_fh)
    if fmt == "JSONL":
        return JSONLWriter(flags, out_fh)
    if fmt == "YAML":
        return YAMLWriter(flags, out_fh)
    if fmt == "MD":
        return MDWriter(flags, out_fh)
    if fmt == "AT":
        return ATWriter(flags, out_fh)
    if fmt == "VF":
        return VFWriter(flags, out_fh)
    if fmt == "TBLN":
        return TBLNWriter(flags, out_fh)
    if fmt == "RAW":
        return RawWriter(flags, out_fh)
    return CSVWriter(flags, out_fh)


def open_output(flags: Flags):
    path = flags.get("out")
    comp = flags.get("oz")
    if not path:
        return sys.stdout, None
    fmt_guess = None
    if not flags.get("out-without-guess"):
        fmt_guess = guess_format_by_ext(path)
    # Handle compression based on extension
    ext = os.path.splitext(path)[1].lower()
    raw = open(path, "wb")
    stream = raw
    if comp in ("gz",) or ext == ".gz":
        stream = gzip.GzipFile(fileobj=raw, mode="wb")
    elif comp in ("bz2",) or ext == ".bz2":
        stream = bz2.BZ2File(raw, mode="wb")
    elif comp in ("xz",) or ext == ".xz":
        stream = lzma.LZMAFile(raw, mode="wb")
    text = io.TextIOWrapper(stream, encoding="utf-8", newline="")
    return text, fmt_guess


# ---------------------------------------------------------------------------
# Orchestration
# ---------------------------------------------------------------------------


def determine_input_format(flags: Flags):
    for f, name in (
        ("icsv", "CSV"),
        ("ijson", "JSON"),
        ("iltsv", "LTSV"),
        ("itbln", "TBLN"),
        ("itext", "TEXT"),
        ("iwidth", "WIDTH"),
        ("iyaml", "YAML"),
    ):
        if flags.get(f):
            return name
    return ""


def determine_output_format(flags: Flags):
    for f, name in (
        ("oat", "AT"),
        ("ocsv", "CSV"),
        ("ojson", "JSON"),
        ("ojsonl", "JSONL"),
        ("oltsv", "LTSV"),
        ("omd", "MD"),
        ("oraw", "RAW"),
        ("otbln", "TBLN"),
        ("ovf", "VF"),
        ("oyaml", "YAML"),
    ):
        if flags.get(f):
            return name
    return "CSV"


def config_path(flags: Flags) -> str:
    p = flags.get("config")
    if p:
        return p
    home = os.path.expanduser("~")
    return os.path.join(home, ".config", "trdsql", "config.json")


def load_config(flags: Flags):
    path = config_path(flags)
    if flags.get("debug"):
        if not os.path.exists(path):
            log(f"configOpen: open {path}: no such file or directory")
    try:
        with open(path, "r") as fh:
            return json.load(fh)
    except Exception:
        return None


def analyze_file(path: str, flags: Flags, suggest_only: bool) -> int:
    try:
        table, fmt = load_table(path, flags)
    except ImportError_ as exc:
        log(f"ERROR: {exc}")
        return 1
    except Exception as exc:
        log(f"ERROR: {exc}")
        return 1

    out = []
    if not suggest_only:
        out.append(f"The table name is {path}.")
        out.append(f"The file type is {fmt}.")
        out.append("")
        out.append("Data types:")
        out.extend(_ascii_table(["column name", "type"], [[c, "text"] for c in table.columns]))
        out.append("")
        out.append("Data samples:")
        out.extend(_ascii_table(table.columns, table.rows[:1]))
        out.append("")
        out.append("Examples:")
    cols = ", ".join(table.columns) if table.columns else "*"
    exe = "trdsql"
    # Mimic binary self name for prefix
    exe = sys.argv[0] if sys.argv else "trdsql"
    out.append(f'{exe} "SELECT {cols} FROM {path}"')
    out.append(f'{exe} "SELECT {cols} FROM {path} WHERE {table.columns[0]} = \'id\'"')
    out.append(f'{exe} "SELECT {table.columns[0]}, count({table.columns[0]}) FROM {path} GROUP BY {table.columns[0]}"')
    out.append(f'{exe} "SELECT {cols} FROM {path} ORDER BY {table.columns[0]} LIMIT 10"')
    sys.stdout.write("\n".join(out) + "\n")
    return 0


def _ascii_table(columns, rows):
    widths = [_display_width(c) for c in columns]
    str_rows = [[str(v) for v in r] for r in rows]
    for r in str_rows:
        for i, v in enumerate(r):
            widths[i] = max(widths[i], _display_width(v))
    border = "+" + "+".join("-" * (w + 2) for w in widths) + "+"
    lines = [border]
    lines.append("| " + " | ".join(_pad_centre(columns[i], widths[i]) for i in range(len(columns))) + " |")
    lines.append(border)
    for r in str_rows:
        lines.append("| " + " | ".join(_pad_cell(r[i], widths[i], _is_numeric(r[i])) for i in range(len(r))) + " |")
    lines.append(border)
    return lines


def load_query(flags: Flags, rest) -> str:
    if flags.get("q"):
        p = flags.get("q")
        try:
            with open(p, "r") as fh:
                return fh.read().strip()
        except Exception as exc:
            log(f"ERROR: {exc}")
            sys.exit(1)
    if rest:
        return " ".join(rest)
    return ""


def main(argv):
    flags = Flags()
    try:
        rest = flags.parse(argv)
    except FlagError as exc:
        sys.stderr.write(str(exc) + "\n")
        sys.stderr.write(load_help_text())
        return 2

    if flags.get("help"):
        sys.stderr.write(load_help_text())
        return 2

    if flags.get("version"):
        sys.stdout.write(f"trdsql version {VERSION}\n")
        return 0

    if flags.get("dblist"):
        cfg = load_config(flags)
        if cfg and isinstance(cfg, dict):
            dbs = cfg.get("database", {})
            for name, info in dbs.items():
                driver = info.get("driver", "")
                sys.stdout.write(f"{name}:{driver}\n")
        return 0

    # Analyze mode.
    if flags.get("a") or flags.get("A"):
        path = flags.get("a") or flags.get("A")
        return analyze_file(path, flags, suggest_only=bool(flags.get("A")))

    if flags.get("debug"):
        load_config(flags)
        driver = flags.get("driver") or "sqlite3"
        log(f"driver: {driver}, dsn: {flags.get('dsn')}")

    query = load_query(flags, rest)
    if not query:
        sys.stderr.write(load_help_text())
        return 2

    tokens = tokenize_sql(query)
    if flags.get("debug"):
        # Collapse runs of space/newline into single entries like Go default
        log(debug_tokens(tokens))

    table_positions = find_tables(tokens)
    if not table_positions and not re.search(r"FROM\s", query, re.IGNORECASE):
        # OK: literal selects like "SELECT 1+1" still run.
        pass
    if not table_positions and re.search(r"FROM\s", query, re.IGNORECASE):
        if flags.get("debug"):
            log("table not found")

    # Deduplicate by resolved path.
    seen = set()
    loaded = []  # [(orig_token, file_path, table)]
    forced = determine_input_format(flags)
    # -t option: additional table load.
    if flags.get("t"):
        p = flags.get("t")
        try:
            tbl, fmt = load_table(p, flags, forced_format=forced)
        except ImportError_ as exc:
            log(str(exc))
            return 1
        loaded.append((p, p, tbl))
        seen.add(p)
    # For SQL-discovered table names
    for pos in table_positions:
        raw = tokens[pos]
        file_path = strip_quotes(raw)
        if file_path in seen:
            continue
        if flags.get("debug"):
            if forced:
                log(f"Set {forced} because forced input: [{raw}]")
            else:
                fmt = guess_format_by_ext(file_path)
                if fmt:
                    log(f"Guess file type as {fmt}: [{raw}]")
                else:
