class FlagError(Exception):
    pass


class Flags:
    """Go-compatible flag parser."""

    STRING_FLAGS = {
        "A", "a", "config", "db", "driver", "dsn", "q", "t",
        "id", "ijq", "inull", "od", "onull", "oq", "out", "oz",
    }
    INT_FLAGS = {"ilr", "ir", "is"}
    BOOL_FLAGS = {
