        "icsv", "ig", "ijson", "iltsv", "itbln", "itext", "iwidth", "iyaml",
        "ih", "inum",
        "oat", "ocsv", "ojson", "ojsonl", "oltsv", "omd", "oraw", "otbln",
        "ovf", "oyaml",
        "oaq", "ocrlf", "oh", "onowrap", "out-without-guess",
    }

    def __init__(self) -> None:
        self.values = {}
        # Defaults
        self.values["id"] = ","
        self.values["od"] = ","
        self.values["oq"] = "\""
        self.values["ir"] = 1
        self.values["is"] = 0
        self.values["ilr"] = 0
        self.values["driver"] = ""
        self.values["dsn"] = ""
        self.values["db"] = ""
        self.values["config"] = ""
        self.values["q"] = ""
        self.values["t"] = ""
        self.values["a"] = ""
        self.values["A"] = ""
        self.values["ijq"] = ""
        self.values["inull"] = ""
        self.values["onull"] = ""
        self.values["out"] = ""
        self.values["oz"] = ""
        for b in self.BOOL_FLAGS:
            self.values[b] = False
        # Explicitly flagged (i.e. user passed the option).
        self.set = set()

    def get(self, name):
        return self.values.get(name)

    def parse(self, argv):
        i = 0
        rest = []
        while i < len(argv):
            arg = argv[i]
            if not arg.startswith("-") or arg == "-":
                rest = argv[i:]
                break
            if arg == "--":
                rest = argv[i + 1:]
                break
            name = arg.lstrip("-")
            value = None
            if "=" in name:
                name, value = name.split("=", 1)
            if name in self.BOOL_FLAGS:
                if value is None:
                    self.values[name] = True
                else:
                    lv = value.lower()
                    if lv in ("true", "1", "t"):
                        self.values[name] = True
                    elif lv in ("false", "0", "f"):
                        self.values[name] = False
                    else:
                        raise FlagError(f'invalid boolean value "{value}" for -{name}: parse error')
                self.set.add(name)
            elif name in self.STRING_FLAGS:
                if value is None:
                    i += 1
                    if i >= len(argv):
                        raise FlagError(f"flag needs an argument: -{name}")
                    value = argv[i]
                self.values[name] = value
                self.set.add(name)
            elif name in self.INT_FLAGS:
                if value is None:
                    i += 1
                    if i >= len(argv):
                        raise FlagError(f"flag needs an argument: -{name}")
                    value = argv[i]
                try:
                    self.values[name] = int(value)
                except ValueError:
                    raise FlagError(f'invalid value "{value}" for flag -{name}: parse error')
                self.set.add(name)
            else:
                raise FlagError(f"flag provided but not defined: -{name}")
            i += 1
        return rest


# ---------------------------------------------------------------------------
# SQL tokeniser (for identifying tables)
# ---------------------------------------------------------------------------

_IDENT_RE = re.compile(r"[A-Za-z0-9_.\-/?!&=@%+~$#:]")


def tokenize_sql(sql: str):
    """Split SQL into tokens resembling trdsql's debug output.

    Whitespace runs become single " " tokens, punctuation is separated, and
    quoted strings (single/double/back-tick) come out intact including quotes.
    """
    tokens = []
    i = 0
    n = len(sql)
    while i < n:
        c = sql[i]
        if c == "\n":
            tokens.append("\n")
            i += 1
        elif c.isspace():
            tokens.append(" ")
            i += 1
        elif c in ("'", '"', "`"):
            quote = c
            j = i + 1
            while j < n:
                if sql[j] == quote:
                    if j + 1 < n and sql[j + 1] == quote:
                        j += 2
                        continue
                    j += 1
                    break
                j += 1
            tokens.append(sql[i:j])
            i = j
        elif _IDENT_RE.match(c):
            j = i
            while j < n and _IDENT_RE.match(sql[j]):
                j += 1
            tokens.append(sql[i:j])
            i = j
        else:
            tokens.append(c)
            i += 1
    return tokens


def debug_tokens(tokens):
    return "[" + "][".join(tokens) + "]"


# Tokens that introduce tables.
_TABLE_INTRO = {"FROM", "JOIN", "UPDATE", "INTO", "TABLE"}


def find_tables(tokens):
    """Return positions in ``tokens`` of table-name tokens."""
    positions = []
    in_table = False
    expect_table = False
    for idx, tok in enumerate(tokens):
        upper = tok.upper()
        if not in_table:
            if upper in _TABLE_INTRO:
                in_table = True
                expect_table = True
            continue
        if tok == " " or tok == "\n":
            continue
        if expect_table:
            # A token right after an intro word or comma.
            if tok == "(":
                # Sub-query. trdsql still tries this (debug showed it). Include.
                positions.append(idx)
                expect_table = False
                # The sub-query ends at matching ')'.
                in_table = False
                continue
            positions.append(idx)
            expect_table = False
            continue
        # Already saw the table; look for what follows.
        if tok == ",":
            expect_table = True
            continue
        # Any other keyword ends the FROM clause.
        if upper in {"WHERE", "ON", "USING", "GROUP", "ORDER", "HAVING",
                     "LIMIT", "OFFSET", "UNION", "EXCEPT", "INTERSECT",
                     "SET", "VALUES", "RETURNING"}:
            in_table = False
            continue
        # Allow AS/alias; keep scanning.
    return positions


def strip_quotes(name: str) -> str:
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"', "`"):
        inner = name[1:-1]
        # Unescape doubled quotes.
        inner = inner.replace(name[0] * 2, name[0])
        return inner
    return name


# ---------------------------------------------------------------------------
# Input format handling
# ---------------------------------------------------------------------------

COMPRESSION_EXTS = {".gz", ".bz2", ".xz"}


def open_input(path: str):
    """Open *path*, transparently decompressing by filename extension."""
    if path == "-":
        data = sys.stdin.buffer.read()
        return io.TextIOWrapper(io.BytesIO(data), encoding="utf-8", newline="")
    _, ext = os.path.splitext(path)
    ext = ext.lower()
    raw = open(path, "rb")
    if ext == ".gz":
        return io.TextIOWrapper(gzip.GzipFile(fileobj=raw), encoding="utf-8", newline="")
    if ext == ".bz2":
        return io.TextIOWrapper(bz2.BZ2File(raw), encoding="utf-8", newline="")
    if ext == ".xz":
        return io.TextIOWrapper(lzma.LZMAFile(raw), encoding="utf-8", newline="")
    return io.TextIOWrapper(raw, encoding="utf-8", newline="")


def guess_format_by_ext(path: str) -> str:
    name = path.lower()
    # strip compression ext
    for ext in (".gz", ".bz2", ".xz", ".zst", ".lz4"):
        if name.endswith(ext):
            name = name[:-len(ext)]
            break
    for ext, fmt in (
        (".csv", "CSV"),
        (".ltsv", "LTSV"),
        (".json", "JSON"),
        (".jsonl", "JSONL"),
        (".yaml", "YAML"),
        (".yml", "YAML"),
        (".tbln", "TBLN"),
        (".tsv", "TSV"),
        (".txt", "TEXT"),
    ):
        if name.endswith(ext):
            return fmt
    return ""


class ImportError_(Exception):
    pass


def read_csv_rows(fh, delimiter=","):
